create or replace function public.apply_billing_plan_event(p_provider text, p_provider_event_id text, p_event_type text, p_organization_id uuid, p_plan text, p_payload jsonb) returns boolean language plpgsql security definer set search_path = 'public', 'pg_catalog' as $$ begin insert into public.billing_events (provider, provider_event_id, organization_id, event_type, payload, status, processed_at) values (p_provider, p_provider_event_id, p_organization_id, p_event_type, p_payload, 'PROCESSED', now()) on conflict (provider_event_id) do nothing; if not found then return true; end if; if p_plan not in ('TRIAL','STARTER','PROFESSIONAL','ENTERPRISE') then raise exception 'Invalid plan'; end if; update public.organizations set plan = p_plan where id = p_organization_id; return true; exception when others then insert into public.billing_events (provider, provider_event_id, organization_id, event_type, payload, status, error) values (p_provider, p_provider_event_id, p_organization_id, p_event_type, p_payload, 'FAILED', sqlerrm) on conflict (provider_event_id) do update set status = 'FAILED', error = excluded.error; raise; end; $$;